Method.Source:
/// <summary>
/// Constructs and returns <c>METKeyVaultSecretHelper</c> object.
/// </summary>
/// <param name = "_clientIdSecretName">Client Id</param>
/// <param name = "_clientSecretName">Client secret</param>
/// <param name = "_tenantIdSecretName">tenant id</param>
/// <returns>METKeyVaultSecretHelper object</returns>
public static METKeyVaultSecretHelper construct(str _clientIdSecretName, str _clientSecretName, str _tenantIdSecretName)
{
    METKeyVaultSecretHelper kleberSystemHelper = new METKeyVaultSecretHelper();

    kleberSystemHelper.parmClientIdSecret(METKeyVaultSecretHelper::getSecretValue(_clientIdSecretName));
    kleberSystemHelper.parmClientSecret(METKeyVaultSecretHelper::getSecretValue(_clientSecretName));
    kleberSystemHelper.parmTenantIdSecret(METKeyVaultSecretHelper::getSecretValue(_tenantIdSecretName));

    return kleberSystemHelper;
}

/// <summary>
/// Gets or sets <c>clientIdSecret</c>.
/// </summary>
/// <param name = "_clientIdSecret"> <c>clientIdSecret</c>. .</param>
/// <returns> <c>clientIdSecret</c>. </returns>
public str parmClientIdSecret(str _clientIdSecret = clientIdSecret)
{
    clientIdSecret = _clientIdSecret;
    return clientIdSecret;
}

/// <summary>
/// Gets or sets <c>clientSecret</c>.
/// </summary>
/// <param name = "_clientSecret"> <c>clientSecret</c>. .</param>
/// <returns> <c>clientSecret</c>. </returns>
public str parmClientSecret(str _clientSecret = clientSecret)
{
    clientSecret = _clientSecret;
    return clientSecret;
}

/// <summary>
/// Gets or sets table <c>tenantIdSecret</c>.
/// </summary>
/// <param name = "_tenantIdSecret"> <c>tenantIdSecret</c>. .</param>
/// <returns> <c>tenantIdSecret</c>. </returns>
public str parmTenantIdSecret(str _tenantIdSecret = tenantIdSecret)
{
    tenantIdSecret = _tenantIdSecret;
    return tenantIdSecret;
}

public static str getSecretValue(str _name)
{
    KeyVaultCertificateTable  certTable = KeyVaultCertificateTable::findByName(_name);
    return KeyVaultCertificateHelper::getManualSecretValue(certTable.RecId);
}
